  "fasting.choose.title": "Puasa",
  "fasting.choose.body": "Amalan peribadi antara anda dan Tuhan. Pilih irama, permudahkan, dan sediakan ruang untuk berdoa.",
  "fasting.choose.modes": "Pilih puasa anda",
  "fasting.mode.intermittent.title": "Irama terputus-putus",
  "fasting.mode.intermittent.short": "16:8, 18:6, 20:4, 5:2 dan 24 jam.",
  "fasting.mode.water.title": "Air cepat",
  "fasting.mode.water.short": "Tiada makanan, air sahaja.",
  "fasting.mode.water.detail": "Puasa alkitabiah yang paling mudah: berhenti makan untuk masa yang ditetapkan dan teruskan minum air. Biarkan rasa lapar yang anda rasa menjadi dorongan untuk berdoa.",
  "fasting.mode.dry.title": "Cepat kering",
  "fasting.mode.dry.short": "Tiada makanan dan tiada air.",
  "fasting.mode.dry.detail": "Puasa mutlak, seperti tiga hari Ester (Ester 4:16). Ia adalah pendek secara semula jadi dan memerlukan penjagaan. Simpan selama 24 jam atau kurang, elakkan haba dan kerja keras, dan pecahkannya dengan teguk kecil.",
  "fasting.mode.until1800.title": "Rehat pada pukul 18:00",
  "fasting.mode.until1800.short": "Puasa sepanjang hari, makan pada pukul 18:00.",
  "fasting.mode.until1800.detail": "Berpuasa pada siang hari dan berbuka dengan hidangan ringkas pada jam 18:00. Pilih tengah malam atau 20:00 malam sebelumnya sebagai permulaan anda. Biarkan kelaparan siang hari menjadikan anda berdoa.",
  "fasting.mode.if16.title": "16:8 irama doa",
  "fasting.mode.if16.short": "16 jam cepat, 8 jam makan.",
  "fasting.mode.if16.detail": "Irama harian, bukan diet: 16 jam berpuasa dan tempoh makan 8 jam. Sediakan waktu untuk berdoa, Kitab Suci dan tenang di hadapan Tuhan.",
  "fasting.mode.if18.title": "18:6 irama doa",
  "fasting.mode.if18.short": "18 jam cepat, 6 jam makan.",
  "fasting.mode.if18.detail": "Irama harian yang lebih panjang dengan puasa 18 jam dan tingkap makan 6 jam. Berikan waktu puasa dengan doa yang jelas dan slot membaca Alkitab.",
  "fasting.mode.if20.title": "20:4 irama doa",
  "fasting.mode.if20.short": "20 jam cepat, 4 jam makan.",
  "fasting.mode.if20.detail": "Irama harian lanjutan dengan puasa 20 jam dan tingkap makan 4 jam. Hanya pilih ini jika irama yang lebih pendek sudah terasa mantap.",
  "fasting.mode.if52.title": "5:2 irama doa",
  "fasting.mode.if52.short": "Dua hari puasa seminggu.",
  "fasting.mode.if52.detail": "Sediakan dua hari seminggu untuk solat dan puasa; lima yang lain adalah normal. Setiap puasa berjalan 24 jam dari 18:00 pada hari yang dipilih hingga 18:00 keesokan harinya.",
  "fasting.mode.if24.title": "24 jam, seminggu sekali",
  "fasting.mode.if24.short": "Satu hari penuh setiap minggu.",
  "fasting.mode.if24.detail": "Satu puasa 24 jam seminggu, dari 18:00 pada hari yang dipilih hingga 18:00 keesokan harinya. Irama mingguan mudah dengan air dibenarkan.",
  "fasting.mode.monk.title": "Rahib cepat (36 jam)",
  "fasting.mode.monk.short": "Puasa air 36 jam mingguan.",
  "fasting.mode.monk.detail": "Puasa air 36 jam mingguan dalam tradisi monastik: selepas makan malam, sepanjang hari penuh, berbuka dengan sarapan ringan. Maju; air sahaja.",
  "fasting.mode.daniel.title": "Daniel berpuasa (21 hari)",
  "fasting.mode.daniel.short": "21 hari makanan tumbuhan mudah.",
  "fasting.mode.daniel.detail": "Puasa separa berdasarkan Daniel 1:12 dan Daniel 10:2–3. Anda masih makan: buah-buahan, sayur-sayuran, kekacang, bijirin penuh, kacang, biji, minyak tumbuhan dan air. Tiada daging, ikan, telur, tenusu, gula tambahan, roti beragi, makanan diproses, kopi atau alkohol.",
  "fasting.mode.daniel.eat": "Makan: buah-buahan, sayur-sayuran, kekacang, bijirin penuh, kacang, biji, minyak tumbuhan, herba dan air.",
  "fasting.mode.daniel.avoid": "Elakkan: daging, ikan, telur, tenusu, gula tambahan atau pemanis, roti beragi, tepung ditapis, makanan yang diproses atau digoreng, kopi, teh, minuman ringan dan alkohol.",
  "fasting.mode.daniel.note": "Puasa Daniel adalah puasa separa. Anda masih makan — anda hanya makan secara berbeza. Ia bukan pantang total dan bukan diet crash.",
  "fasting.mode.custom.title": "Custom cepat",
  "fasting.mode.custom.short": "Pilih permulaan dan panjang anda sendiri.",
  "fasting.mode.custom.detail": "Tetapkan masa mula dan panjang anda sendiri untuk cepat air yang mudah. Pastikan ia berada dalam lingkungan yang selamat dan biarkan masa dibentuk dengan doa.",
  "fasting.mode.rhythm": "Irama doa",
  "fasting.mode.rhythmBody": "Semasa waktu berpuasa, sediakan satu slot yang lebih panjang untuk berdoa dan Kitab Suci. Biarkan setiap rasa lapar kembalikan perhatian anda kepada Tuhan.",
  "fasting.mode.safety": "Sebelum anda bermula",
  "fasting.mode.safetyBody": "Bercakap dengan doktor sebelum berpuasa jika anda menghidap diabetes, mengambil ubat secara tetap, mengandung atau menyusu, berumur di bawah 18 tahun, atau mempunyai sejarah gangguan makan. Dalam kes tersebut, pilih irama terputus-putus atau puasa Daniel daripada puasa air yang panjang atau kering.",
  "fasting.mode.drySafety": "Puasa kering bukan untuk pemula. Jangan bersenam, elakkan haba, dan berhenti pada sebarang tanda pening atau kekeliruan.",
  "fasting.mode.choose": "Pilih ini cepat",
  "fasting.mode.badge.partial": "Separa cepat",
  "fasting.mode.badge.advanced": "Maju",
  "fasting.teaching.title": "Apa yang dikira sebagai puasa?",
  "fasting.teaching.body": "Dalam Alkitab, berpuasa adalah menahan diri dari makanan untuk masa yang ditetapkan, untuk tujuan rohani dan di hadapan Tuhan. Air boleh diambil (kebanyakan puasa) atau ditahan (puasa mutlak, seperti Ester 4:16). Berhenti menggunakan gula, kopi atau media sosial boleh menjadi satu disiplin yang baik — tetapi dengan sendirinya ia tidak berpuasa. KOINO memanggil sesuatu sebagai puasa hanya apabila makanan benar-benar ditinggalkan.",
  "fasting.teaching.scripture": "\"Apabila kamu berpuasa, janganlah kelihatan muram... Bapamu yang melihat yang tersembunyi akan memberi upah kepadamu.\" — Matius 6:16–18",
  "fasting.teaching.open": "Baca lagi",
  "fasting.teaching.close": "tutup",
  "fasting.tips.title": "Hikmah puasa",
  "fasting.tips.start.title": "Mulakan secara beransur-ansur",
  "fasting.tips.start.body": "Mulakan dengan melangkau satu hidangan, atau puasa siang hari sehingga jam 18:00, sebelum mencuba puasa berbilang hari.",
  "fasting.tips.prayer.title": "Utamakan doa dan Kitab Suci",
  "fasting.tips.prayer.body": "Gantikan masa yang anda akan luangkan untuk makan atau menatal dengan doa, membaca Alkitab, atau renungan tenang di hadapan Tuhan.",
  "fasting.tips.medical.title": "Periksa keselamatan perubatan",
  "fasting.tips.medical.body": "Bercakap dengan doktor sebelum berpuasa jika anda menghidap diabetes, mengambil ubat secara tetap, mengandung atau menyusu, berumur di bawah 18 tahun, atau mempunyai sejarah gangguan makan. Dalam kes tersebut, pilih irama terputus-putus atau puasa Daniel daripada puasa air yang panjang atau kering.",
  "fasting.tips.break.title": "Berbuka puasa lebih lama dengan lembut",
  "fasting.tips.break.body": "Berbuka dengan makanan ringan dan mudah dihadam. Jangan sambut akhir puasa dengan jamuan berat.",
  "fasting.tips.truth.title": "Puasa sebenar bermaksud menahan diri daripada makan",
  "fasting.tips.truth.body": "Gula, kopi atau media sosial sahaja tidak berpuasa, walaupun ia berfaedah. Lihat kad pengajaran di atas.",
  "fasting.tips.more": "Lebih hikmah",
  "fasting.tips.water.title": "Minum air",
  "fasting.tips.water.body": "Kecuali anda sedang berpuasa kering, simpan air berdekatan dan minum secara berterusan.",
  "fasting.tips.stop.title": "Berhenti jika ada sesuatu yang tidak kena",
  "fasting.tips.stop.body": "Pening, pitam atau keliru adalah tanda untuk berbuka. Jangan menolaknya.",
  "fasting.tips.secret.title": "Simpanlah antara kamu dan Tuhan",
  "fasting.tips.secret.body": "Jangan berpuasa untuk menarik perhatian orang. Yesus menunjukkan kita kepada Bapa yang melihat secara rahsia.",
  "fasting.tips.rest.title": "Rehat dan tidur",
  "fasting.tips.rest.body": "Hari puasa yang panjang bukanlah masa untuk latihan berat. Berjalan dengan lembut, berehat dan tidur.",
